css:
/* Project Diesel Fill Print — RTL A4 voucher, wkhtmltopdf-safe.
   Palette: dark slate #24364a structure + teal #0f766e accent (print-safe).
   Printable area fit: A4 210mm - 2x10mm margins = 190mm. The root is capped at
   190mm with a 2.5mm inner gutter, box-sizing is border-box everywhere, and
   every table is table-layout:fixed at width:100% so no cell content can
   expand a table past the printable width (old-WebKit nowrap bug). */
.card-pf {
  direction: rtl;
  text-align: right;
  font-family: "Noto Sans Arabic", "Noto Sans", "Segoe UI", Tahoma, Arial, sans-serif;
  color: #1f2937;
  font-size: 10.5px;
  line-height: 1.5;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.card-pf, .card-pf * { -webkit-box-sizing: border-box; box-sizing: border-box; }
.card-pf table { width: 100%; max-width: 100%; table-layout: fixed; border-collapse: collapse; }
.card-pf th, .card-pf td { word-wrap: break-word; overflow-wrap: anywhere; }
.card-pf img { border: 0; }
.card-pf bdi { direction: ltr; unicode-bidi: embed; }

/* ---------- header ---------- */
.card-pf .pf-head { border-bottom: 2.5px solid #24364a; }
.card-pf .pf-head td { vertical-align: middle; padding: 0 0 8px 0; border: 0; }
.card-pf .pf-logo-cell { width: 104px; text-align: right; }
.card-pf .pf-logo { max-height: 62px; max-width: 96px; }
.card-pf .pf-brand { padding-right: 8px; }
.card-pf .pf-company { font-size: 17px; font-weight: 700; color: #24364a; }
.card-pf .pf-company-meta { margin-top: 2px; color: #5f6b7a; font-size: 9px; }
.card-pf .pf-company-meta span { margin-left: 12px; }
.card-pf .pf-title { text-align: left; width: 36%; }
.card-pf .pf-title-main { font-size: 15px; font-weight: 700; color: #0f766e; }
.card-pf .pf-title-en { font-size: 8.5px; color: #8b97a5; letter-spacing: 1px; text-transform: uppercase; }
.card-pf .pf-docno { font-size: 12px; font-weight: 600; color: #1f2937; margin-top: 2px; }
.card-pf .pf-docdate { font-size: 9.5px; color: #5f6b7a; margin-top: 1px; }
.card-pf .pf-badge { display: inline-block; margin-top: 3px; padding: 1px 9px; border-radius: 8px; font-size: 9px; font-weight: 700; border: 1px solid #b9c4d0; }
.card-pf .pf-badge-draft { color: #5f6b7a; background: #eef2f7 !important; }
.card-pf .pf-badge-cancelled { color: #ffffff !important; border-color: #b42318; background: #b42318 !important; }

/* ---------- meta ---------- */
.cpf-dsl .pf-meta { margin: 8px 0 0; }
.cpf-dsl .pf-meta th, .cpf-dsl .pf-meta td { border: 1px solid #dde4ec; padding: 5px 8px; font-size: 10px; vertical-align: middle; overflow: hidden; }
.cpf-dsl .pf-meta th { width: 15%; background: #eef2f7 !important; color: #24364a; font-weight: 700; white-space: normal; }
.cpf-dsl .pf-meta td { width: 35%; }
.cpf-dsl .pf-meta .pf-blank { background: #ffffff !important; }

/* ---------- amount band ---------- */
.cpf-dsl .pf-band { margin-top: 10px; border-collapse: separate !important; border-spacing: 6px 0; page-break-inside: avoid; }
.cpf-dsl .pf-box { width: 33.33%; border: 1px solid #b9c4d0; border-radius: 5px; background: #eef2f7 !important; text-align: center; padding: 8px 6px; overflow: hidden; }
.cpf-dsl .pf-box-label { display: block; font-size: 9.5px; color: #5f6b7a; font-weight: 700; margin-bottom: 3px; }
.cpf-dsl .pf-box-value { display: block; font-size: 17px; font-weight: 700; color: #24364a; }
.cpf-dsl .pf-box-accent { background: #0f766e !important; border-color: #0f766e !important; }
.cpf-dsl .pf-box-accent .pf-box-label { color: #d9ece9 !important; }
.cpf-dsl .pf-box-accent .pf-box-value { color: #ffffff !important; font-size: 18px; }
.cpf-dsl .pf-inwords { margin-top: 6px; font-size: 10px; color: #24364a; background: #eef2f7 !important; border: 1px dashed #b9c4d0; padding: 4px 10px; border-radius: 3px; white-space: normal; word-wrap: break-word; word-break: break-word; overflow-wrap: anywhere; }

/* ---------- remarks ---------- */
.cpf-dsl .pf-remarks { margin-top: 9px; border: 1px solid #dde4ec; border-radius: 3px; page-break-inside: avoid; }
.cpf-dsl .pf-remarks-title { background: #eef2f7 !important; color: #24364a; font-weight: 700; font-size: 9.5px; padding: 3px 8px; border-bottom: 1px solid #dde4ec; }
.cpf-dsl .pf-remarks-text { padding: 5px 8px; min-height: 24px; white-space: pre-line; word-wrap: break-word; }

/* ---------- signatures + footer ---------- */
.card-pf .pf-sign { margin-top: 22px; page-break-inside: avoid; }
.card-pf .pf-sign td { width: 33.33%; padding: 0 12px; text-align: center; border: 0; }
.card-pf .pf-sign-role { font-size: 10.5px; font-weight: 700; color: #24364a; }
.card-pf .pf-sign-line { height: 32px; border-bottom: 1.2px solid #5f6b7a; margin: 5px 8px 3px; }
.card-pf .pf-sign-hint { font-size: 8.5px; color: #8b97a5; }
.card-pf .pf-footer { margin-top: 14px; padding-top: 5px; border-top: 1px solid #dde4ec; text-align: center; font-size: 8.5px; color: #8b97a5; }

html:
{#- Project Diesel Fill Print — clean RTL A4 voucher.
    Data-driven from the system (Company record + document); labels via _()
    with the DocType's own msgids. Does not render {{ letter_head }} (draws
    its own company header). -#}
{%- set flt = frappe.utils.flt -%}
{%- set L = doc.meta.get_label -%}
{%- set company = frappe.get_doc("Company", doc.company) if doc.company else None -%}
{%- set company_name = (company.company_name or company.name) if company else (doc.company or "") -%}
{%- set company_logo = company.get("company_logo") if company else None -%}
{%- set company_tax = company.get("tax_id") if company else None -%}
{%- set company_phone = company.get("phone_no") if company else None -%}
{%- set title_main = _(doc.doctype) -%}
{%- set supplier_disp = (frappe.db.get_value("Supplier", doc.supplier, "supplier_name") or doc.supplier) if doc.supplier else "" -%}
{%- set project_disp = (frappe.db.get_value("Project", doc.project, "project_name") or doc.project) if doc.project else "" -%}
{%- set equip_name = frappe.db.get_value("Card Equipment", doc.card_equipment, "equipment_name") if doc.card_equipment else None -%}
{%- set equip_disp = ((equip_name ~ " (" ~ doc.card_equipment ~ ")") if (equip_name and equip_name != doc.card_equipment) else (doc.card_equipment or "")) -%}
<div class="card-pf cpf-dsl" dir="rtl">

  <table class="pf-head"><tr>
    {%- if company_logo %}
    <td class="pf-logo-cell"><img class="pf-logo" src="{{ company_logo }}" alt=""></td>
    {%- endif %}
    <td class="pf-brand">
      <div class="pf-company">{{ company_name|e }}</div>
      <div class="pf-company-meta">
        {%- if company_tax %}<span>{{ _("Tax ID") }}: <bdi>{{ company_tax|e }}</bdi></span>{% endif -%}
        {%- if company_phone %}<span>{{ _("Phone") }}: <bdi>{{ company_phone|e }}</bdi></span>{% endif -%}
      </div>
    </td>
    <td class="pf-title">
      <div class="pf-title-main">{{ title_main }}</div>
      {%- if title_main != doc.doctype %}<div class="pf-title-en">{{ doc.doctype }}</div>{% endif %}
      <div class="pf-docno"><bdi>{{ doc.name }}</bdi></div>
      <div class="pf-docdate">{{ _(L("date")) }}: <bdi>{{ frappe.utils.formatdate(doc.date) if doc.date else "" }}</bdi></div>
      {%- if doc.docstatus == 0 %}<span class="pf-badge pf-badge-draft">{{ _("Draft") }}</span>
      {%- elif doc.docstatus == 2 %}<span class="pf-badge pf-badge-cancelled">{{ _("Cancelled") }}</span>{% endif %}
    </td>
  </tr></table>

  {%- set pairs = [
      (_(L("project")), project_disp),
      (_(L("supplier")), supplier_disp),
      (_(L("card_equipment")), equip_disp)
    ]|selectattr("1")|list -%}
  {%- if pairs %}
  <table class="pf-meta">
    {%- for row in pairs|batch(2) %}
    <tr>
      {%- for p in row %}
      <th>{{ p[0] }}</th><td>{{ p[1]|e }}</td>
      {%- endfor %}
      {%- for i in range(2 - row|length) %}<th class="pf-blank"></th><td class="pf-blank"></td>{% endfor %}
    </tr>
    {%- endfor %}
  </table>
  {%- endif %}

  <table class="pf-band"><tr>
    <td class="pf-box">
      <span class="pf-box-label">{{ _(L("litres")) }}</span>
      <span class="pf-box-value">{{ "%g"|format(flt(doc.litres, 3)) }}</span>
    </td>
    <td class="pf-box">
      <span class="pf-box-label">{{ _(L("unit_price")) }}</span>
      <span class="pf-box-value">{{ doc.get_formatted("unit_price") }}</span>
    </td>
    <td class="pf-box pf-box-accent">
      <span class="pf-box-label">{{ _(L("amount")) }}</span>
      <span class="pf-box-value">{{ doc.get_formatted("amount") }}</span>
    </td>
  </tr></table>
  {%- if flt(doc.amount) %}
  <div class="pf-inwords">{{ _("In Words") }}: {{ frappe.utils.money_in_words(flt(doc.amount)) }}</div>
  {%- endif %}

  {%- if doc.remarks %}
  <div class="pf-remarks">
    <div class="pf-remarks-title">{{ _(L("remarks")) }}</div>
    <div class="pf-remarks-text">{{ doc.remarks|e }}</div>
  </div>
  {%- endif %}

  <table class="pf-sign"><tr>
    <td>
      <div class="pf-sign-role">{{ _("Prepared By") }}</div>
      <div class="pf-sign-line"></div>
      <div class="pf-sign-hint">{{ _("Name / Signature") }}</div>
    </td>
    <td>
      <div class="pf-sign-role">{{ _("Received By") }}</div>
      <div class="pf-sign-line"></div>
      <div class="pf-sign-hint">{{ _("Name / Signature") }}</div>
    </td>
    <td>
      <div class="pf-sign-role">{{ _("Approved By") }}</div>
      <div class="pf-sign-line"></div>
      <div class="pf-sign-hint">{{ _("Name / Signature") }}</div>
    </td>
  </tr></table>

  <div class="pf-footer">{{ company_name|e }} &middot; <bdi>{{ doc.name }}</bdi> &middot; {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</div>
</div>
